def solve(s):
    # Only process if input is a string; otherwise return empty list as per spec.
    if not isinstance(s, str):
        return []
    if not s:
        return []
    res = []
    prev = s[0]
    cnt = 1
    for ch in s[1:]:
        if ch == prev:
            cnt += 1
        else:
            res.append([prev, cnt])
            prev = ch
            cnt = 1
    res.append([prev, cnt])
    return res

